"use client";

import React, { useState, useEffect } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { KeyRound, Lock, CheckCircle } from "lucide-react";
import Link from "next/link";

function ResetPasswordForm() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const token = searchParams.get("token");

  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [status, setStatus] = useState<
    "idle" | "loading" | "success" | "error"
  >("idle");
  const [errorMessage, setErrorMessage] = useState("");

  useEffect(() => {
    if (!token) {
      setStatus("error");
      setErrorMessage("Invalid or missing reset token.");
    }
  }, [token]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!token) return;

    if (password !== confirmPassword) {
      setStatus("error");
      setErrorMessage("Passwords do not match.");
      return;
    }

    if (password.length < 8) {
      setStatus("error");
      setErrorMessage("Password must be at least 8 characters long.");
      return;
    }

    setStatus("loading");
    setErrorMessage("");

    try {
      const res = await fetch("/api/auth/reset-password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "reset", token, password }),
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || "Failed to reset password");
      }

      setStatus("success");
      // Redirect after a few seconds
      setTimeout(() => {
        router.push("/login?reset=success");
      }, 3000);
    } catch (err: any) {
      setStatus("error");
      setErrorMessage(err.message || "An error occurred");
    }
  };

  if (!token) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col justify-center py-12 px-4 sm:px-6 lg:px-8">
        <div className="sm:mx-auto sm:w-full sm:max-w-md bg-white py-8 px-4 shadow-xl sm:rounded-2xl border border-slate-100 text-center">
          <h2 className="text-xl font-bold text-slate-900">Invalid Link</h2>
          <p className="mt-2 text-sm text-slate-600 mb-6">
            This password reset link is missing or invalid.
          </p>
          <Link
            href="/forgot-password"
            className="text-teal-900 font-bold hover:underline"
          >
            Request a new link
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col justify-center py-12 px-4 sm:px-6 lg:px-8">
      <div className="sm:mx-auto sm:w-full sm:max-w-md">
        <div className="flex justify-center mb-6">
          <div className="w-16 h-16 rounded-full bg-teal-100 flex items-center justify-center text-teal-900 shadow-inner border border-teal-200">
            <KeyRound size={32} />
          </div>
        </div>
        <h2 className="text-center font-serif text-3xl font-bold tracking-tight text-slate-900">
          Create new password
        </h2>
        <p className="mt-2 text-center text-sm text-slate-600">
          Your new password must be different from previous used passwords.
        </p>
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md">
        <div className="bg-white py-8 px-4 shadow-xl shadow-slate-200/50 sm:rounded-2xl sm:px-10 border border-slate-100">
          {status === "success" ? (
            <div className="text-center flex flex-col items-center gap-4">
              <div className="w-16 h-16 rounded-full bg-green-50 flex items-center justify-center text-green-600 mb-2">
                <CheckCircle size={32} />
              </div>
              <h3 className="text-xl font-bold text-slate-900">
                Password Reset Complete
              </h3>
              <p className="text-sm text-slate-600 mb-6">
                Your password has been successfully reset. Redirecting to
                login...
              </p>
            </div>
          ) : (
            <form className="space-y-6" onSubmit={handleSubmit}>
              {status === "error" && (
                <div className="p-3 rounded-lg bg-red-50 text-red-600 text-sm border border-red-100 font-medium text-center">
                  {errorMessage}
                </div>
              )}

              <div>
                <label
                  htmlFor="password"
                  className="block text-sm font-bold text-slate-700"
                >
                  New Password
                </label>
                <div className="mt-2 relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                    <Lock size={18} />
                  </div>
                  <input
                    id="password"
                    name="password"
                    type="password"
                    required
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="block w-full pl-10 pr-3 py-3 border border-slate-200 rounded-xl shadow-sm focus:ring-2 focus:ring-teal-900 focus:border-teal-900 sm:text-sm transition-all"
                    placeholder="••••••••"
                  />
                </div>
              </div>

              <div>
                <label
                  htmlFor="confirmPassword"
                  className="block text-sm font-bold text-slate-700"
                >
                  Confirm Password
                </label>
                <div className="mt-2 relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-slate-400">
                    <Lock size={18} />
                  </div>
                  <input
                    id="confirmPassword"
                    name="confirmPassword"
                    type="password"
                    required
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    className="block w-full pl-10 pr-3 py-3 border border-slate-200 rounded-xl shadow-sm focus:ring-2 focus:ring-teal-900 focus:border-teal-900 sm:text-sm transition-all"
                    placeholder="••••••••"
                  />
                </div>
              </div>

              <div>
                <button
                  type="submit"
                  disabled={
                    status === "loading" || !password || !confirmPassword
                  }
                  className="w-full flex justify-center py-3 px-4 border border-transparent rounded-xl shadow-sm text-sm font-bold text-white bg-teal-900 hover:bg-teal-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-teal-900 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  {status === "loading" ? "Resetting..." : "Reset password"}
                </button>
              </div>
            </form>
          )}
        </div>
      </div>
    </div>
  );
}

export default function ResetPasswordPage() {
  return (
    <React.Suspense
      fallback={
        <div className="min-h-screen bg-slate-50 flex flex-col justify-center py-12 sm:px-6 lg:px-8 items-center">
          <div className="animate-pulse flex flex-col items-center">
            <div className="w-12 h-12 bg-slate-200 rounded-full mb-4"></div>
            <div className="h-4 bg-slate-200 rounded w-32"></div>
          </div>
        </div>
      }
    >
      <ResetPasswordForm />
    </React.Suspense>
  );
}

"use client";

import { useState } from "react";
import Image from "next/image";
import {
  ArrowLeft,
  ArrowRight,
  Check,
  Users,
  Calendar as CalendarIcon,
  ShieldCheck,
} from "lucide-react";

import { createBookingAndPay } from "@/app/actions/booking";

export default function BookingWizard({
  room,
  user,
}: {
  room: any;
  user: any;
}) {
  const [step, setStep] = useState(1);
  const [guests, setGuests] = useState(2);
  const [checkIn, setCheckIn] = useState<string>("");
  const [checkOut, setCheckOut] = useState<string>("");
  const [isProcessing, setIsProcessing] = useState(false);

  // Formats price
  const formatPrice = (amount: number) => {
    return new Intl.NumberFormat("en-NG", {
      style: "currency",
      currency: "NGN",
      maximumFractionDigits: 0,
    }).format(amount);
  };

  const getNumberOfNights = () => {
    if (!checkIn || !checkOut) return 0;
    const diffTime = Math.abs(
      new Date(checkOut).getTime() - new Date(checkIn).getTime(),
    );
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const nights = getNumberOfNights();
  const total = nights * room.pricePerNight;
  const commission = total * 0.1; // 10% deducted from hotel payout

  const handleNext = () => setStep((prev) => prev + 1);
  const handleBack = () => setStep((prev) => prev - 1);

  const handlePayment = async () => {
    setIsProcessing(true);
    try {
      const data = await createBookingAndPay({
        roomId: room.id,
        hotelId: room.hotelId,
        checkIn,
        checkOut,
        guests,
        total,
      });

      if (data.success && data.authorizationUrl) {
        window.location.href = data.authorizationUrl;
      } else {
        alert(data.error || "Failed to initiate payment");
        setIsProcessing(false);
      }
    } catch (e) {
      alert("Network error");
      setIsProcessing(false);
    }
  };

  return (
    <div className="max-w-[1000px] mx-auto px-4 md:px-12 pt-28 pb-32">
      {/* Progress Bar */}
      <div className="mb-12">
        <div className="flex justify-between items-center relative">
          <div className="absolute left-0 top-1/2 -translate-y-1/2 w-full h-1 bg-gray-100 -z-10 rounded-full"></div>
          <div
            className="absolute left-0 top-1/2 -translate-y-1/2 h-1 bg-green-600 -z-10 rounded-full transition-all duration-500"
            style={{ width: `${((step - 1) / 3) * 100}%` }}
          ></div>

          {[1, 2, 3, 4].map((num) => (
            <div
              key={num}
              className={`w-10 h-10 rounded-full flex items-center justify-center font-bold text-sm transition-colors ${
                step >= num
                  ? "bg-green-600 text-white shadow-md"
                  : "bg-white text-gray-300 border-2 border-gray-100"
              }`}
            >
              {step > num ? <Check size={18} /> : num}
            </div>
          ))}
        </div>
      </div>

      <div className="flex flex-col md:flex-row gap-12">
        {/* Left Side: Wizard Forms */}
        <div className="w-full md:w-3/5">
          {step === 1 && (
            <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <h2 className="text-3xl font-bold tracking-tight text-gray-900">
                Who&apos;s coming?
              </h2>
              <div className="p-6 border border-gray-200 rounded-3xl flex justify-between items-center bg-gray-50/50">
                <div>
                  <h3 className="font-bold text-lg text-gray-900">Guests</h3>
                  <p className="text-gray-500">
                    Maximum capacity: {room.capacity}
                  </p>
                </div>
                <div className="flex items-center gap-4">
                  <button
                    onClick={() => setGuests(Math.max(1, guests - 1))}
                    className="w-12 h-12 rounded-full border border-gray-300 flex items-center justify-center text-gray-600 hover:border-gray-900 hover:text-gray-900 transition-colors"
                  >
                    -
                  </button>
                  <span className="text-2xl font-bold w-6 text-center">
                    {guests}
                  </span>
                  <button
                    onClick={() =>
                      setGuests(Math.min(room.capacity, guests + 1))
                    }
                    className="w-12 h-12 rounded-full border border-gray-300 flex items-center justify-center text-gray-600 hover:border-gray-900 hover:text-gray-900 transition-colors"
                  >
                    +
                  </button>
                </div>
              </div>
              <button
                onClick={handleNext}
                className="w-full bg-gray-900 text-white font-semibold py-4 rounded-full hover:bg-green-600 transition-colors text-lg mt-8"
              >
                Continue
              </button>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="flex items-center gap-4 mb-8">
                <button
                  onClick={handleBack}
                  className="p-2 hover:bg-gray-100 rounded-full transition-colors"
                >
                  <ArrowLeft size={24} />
                </button>
                <h2 className="text-3xl font-bold tracking-tight text-gray-900">
