"use client";

import React, { useState } from "react";
import { Settings, ShieldCheck, Loader2, CheckCircle2 } from "lucide-react";
import { useRouter } from "next/navigation";

export default function SecurityClient({ user }: { user: any }) {
  const router = useRouter();
  const [isSaving, setIsSaving] = useState(false);
  const [success, setSuccess] = useState(false);
  const [errorMsg, setErrorMsg] = useState("");

  const [formData, setFormData] = useState({
    password: "",
    confirmPassword: "",
  });

  const handle2FAToggle = async () => {
    setIsSaving(true);
    try {
      const res = await fetch("/api/users/security", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ twoFactorEnabled: !user.twoFactorEnabled }),
      });

      if (res.ok) {
        router.refresh();
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsSaving(false);
    }
  };

  const handlePasswordUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg("");

    if (formData.password !== formData.confirmPassword) {
      setErrorMsg("Passwords do not match");
      return;
    }

    if (formData.password.length < 12) {
      setErrorMsg("Password must be at least 12 characters");
      return;
    }

    setIsSaving(true);

    try {
      const res = await fetch("/api/users/security", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password: formData.password }),
      });

      if (res.ok) {
        setSuccess(true);
        setFormData({ password: "", confirmPassword: "" });
        setTimeout(() => {
          setSuccess(false);
        }, 2000);
      } else {
        const data = await res.json();
        setErrorMsg(data.error || "Failed to update password");
      }
    } catch (error) {
      console.error(error);
      setErrorMsg("An error occurred");
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-8 animate-in fade-in duration-500 slide-in-from-bottom-4">
      <div className="flex items-center justify-between mb-8 pb-6 border-b border-slate-100">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Security & 2FA</h2>
          <p className="text-slate-500 mt-1">
            Manage your account security and authentication methods
          </p>
        </div>
      </div>

      <div className="flex flex-col gap-8 max-w-2xl">
        {/* 2FA Section */}
        <div className="flex flex-col sm:flex-row items-start justify-between p-6 bg-slate-50 rounded-xl border border-slate-100 gap-4">
          <div className="flex items-start gap-4">
            <div className="mt-1">
              <ShieldCheck
                className={
                  user.twoFactorEnabled ? "text-teal-600" : "text-slate-400"
                }
                size={24}
              />
            </div>
            <div>
              <h3 className="font-bold text-slate-900">
                Two-Factor Authentication (2FA)
              </h3>
              <p className="text-sm text-slate-500 mt-1 mb-3">
                Protect your account with an extra layer of security.
              </p>
              {user.twoFactorEnabled ? (
                <span className="inline-flex px-2 py-1 rounded bg-teal-100 text-teal-800 text-xs font-bold">
                  Active
                </span>
              ) : (
                <span className="inline-flex px-2 py-1 rounded bg-slate-200 text-slate-600 text-xs font-bold">
                  Disabled
                </span>
              )}
            </div>
          </div>
          <button
            onClick={handle2FAToggle}
            disabled={isSaving}
            className="px-4 py-2 text-sm font-semibold text-slate-700 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 transition-colors disabled:opacity-50 whitespace-nowrap"
          >
            {user.twoFactorEnabled ? "Disable 2FA" : "Enable 2FA"}
          </button>
        </div>

        {/* Change Password Section */}
        <div className="flex flex-col p-6 bg-white rounded-xl border border-slate-100">
          <div className="flex items-start gap-4 mb-6">
            <div className="mt-1">
              <Settings className="text-slate-400" size={24} />
            </div>
            <div>
              <h3 className="font-bold text-slate-900">Change Password</h3>
              <p className="text-sm text-slate-500 mt-1">
                Ensure your password is at least 12 characters and highly
                secure.
              </p>
            </div>
          </div>

          <form
            onSubmit={handlePasswordUpdate}
            className="flex flex-col gap-4 ml-10"
          >
            {errorMsg && (
              <div className="p-3 rounded-lg bg-red-50 text-red-600 text-sm font-medium border border-red-100">
                {errorMsg}
              </div>
            )}

            <div className="flex flex-col gap-1.5">
              <label className="text-sm font-bold text-slate-700">
                New Password
              </label>
              <input
                type="password"
                value={formData.password}
                onChange={(e) =>
                  setFormData({ ...formData, password: e.target.value })
                }
                className="w-full md:w-2/3 px-4 py-2 border border-slate-200 rounded-lg bg-slate-50 focus:bg-white focus:ring-1 focus:ring-teal-900 focus:border-teal-900 transition-colors"
                placeholder="At least 12 characters"
              />
            </div>

            <div className="flex flex-col gap-1.5">
              <label className="text-sm font-bold text-slate-700">
                Confirm New Password
              </label>
              <input
                type="password"
                value={formData.confirmPassword}
                onChange={(e) =>
                  setFormData({ ...formData, confirmPassword: e.target.value })
                }
                className="w-full md:w-2/3 px-4 py-2 border border-slate-200 rounded-lg bg-slate-50 focus:bg-white focus:ring-1 focus:ring-teal-900 focus:border-teal-900 transition-colors"
              />
            </div>

            <div className="mt-2 flex">
              <button
                type="submit"
                disabled={isSaving || success || !formData.password}
                className={`min-w-[140px] px-5 py-2.5 rounded-lg text-sm font-semibold text-white transition-all shadow-sm flex items-center justify-center gap-2 ${success ? "bg-green-600" : "bg-teal-900 hover:bg-teal-800 disabled:opacity-70"}`}
              >
                {success ? (
                  <>
                    <CheckCircle2 size={16} />
                    Updated!
                  </>
                ) : isSaving && formData.password ? (
                  <>
                    <Loader2 size={16} className="animate-spin" />
                    Updating...
                  </>
                ) : (
                  "Update Password"
                )}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

"use server";

import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { apiClient } from "@/lib/api-client";

export async function loginAction(prevState: any, formData: FormData) {
  const identifier = formData.get("identifier") as string;
  const password = formData.get("password") as string;
  const redirectTo = (formData.get("redirectTo") as string) || "/";

  if (!identifier || !password) {
    return { error: "Missing fields" };
  }

  try {
    const response = await apiClient.post("/api/auth/login", {
      identifier,
      password,
    });

    if (!response.success) {
      return { error: response.error?.message || "Invalid credentials" };
    }

    const { accessToken, refreshToken } = response.data;

    const cookieStore = await cookies();
    cookieStore.set("accessToken", accessToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      path: "/",
      maxAge: 15 * 60,
    });

    cookieStore.set("refreshToken", refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      path: "/",
      maxAge: 7 * 24 * 60 * 60,
    });
  } catch (error) {
    console.error("Login error:", error);
    return { error: "Something went wrong. Please try again." };
  }

  redirect(redirectTo);
}

export async function registerAction(prevState: any, formData: FormData) {
  const fullName = formData.get("fullName") as string;
  const email = formData.get("email") as string;
  const phone = formData.get("phone") as string;
  const password = formData.get("password") as string;
  const roleValue = formData.get("role") as string;

  if (!fullName || !email || !phone || !password || !roleValue) {
    return { error: "All fields are required" };
  }

  const role = roleValue === "HOTEL_MANAGER" ? "HOTEL_MANAGER" : "BOOKER";

  try {
    const response = await apiClient.post("/api/auth/register", {
      fullName,
      email,
      phone,
      password,
      role,
    });

    if (!response.success) {
      return { error: response.error?.message || "Failed to create account" };
    }

    const { accessToken, refreshToken } = response.data;

    const cookieStore = await cookies();
    cookieStore.set("accessToken", accessToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      path: "/",
      maxAge: 15 * 60,
    });

    cookieStore.set("refreshToken", refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "lax",
      path: "/",
      maxAge: 7 * 24 * 60 * 60,
    });
  } catch (error) {
    console.error("Register error:", error);
    return { error: "Failed to create account. Please try again." };
  }

  redirect("/");
}

export async function logoutAction() {
  const cookieStore = await cookies();
  cookieStore.delete("accessToken");
  cookieStore.delete("refreshToken");
  redirect("/login");
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { hash } from "bcryptjs";
import { randomBytes } from "crypto";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { action } = body;

    if (action === "request") {
      const { email } = body;
      if (!email)
        return NextResponse.json(
          { error: "Email is required" },
          { status: 400 },
        );

      const user = await prisma.user.findUnique({ where: { email } });

      if (user) {
        // Generate a secure reset token
        const resetToken = randomBytes(32).toString("hex");
        // Set expiry to 1 hour from now
        const resetTokenExpiry = new Date(Date.now() + 60 * 60 * 1000);

        await prisma.user.update({
          where: { id: user.id },
          data: { resetToken, resetTokenExpiry },
        });

        // In a real application, you would send an email here using SendGrid, Resend, etc.
        // For MVP/Development, we will log the reset link to the server console.
        const resetUrl = `${req.headers.get("origin") || "http://localhost:3000"}/reset-password?token=${resetToken}`;
        console.log(
          `\n\n======================================================`,
        );
        console.log(`🔐 PASSWORD RESET REQUEST for ${email}`);
        console.log(`Click this link to reset: ${resetUrl}`);
        console.log(
          `======================================================\n\n`,
        );
      }

      // Always return 200 even if user not found to prevent email enumeration
      return NextResponse.json(
        { message: "If an account exists, a reset link has been sent." },
        { status: 200 },
      );
    } else if (action === "reset") {
      const { token, password } = body;

      if (!token || !password) {
        return NextResponse.json(
          { error: "Token and new password are required" },
          { status: 400 },
        );
      }

      // Find user with this token and ensure it hasn't expired
      const user = await prisma.user.findFirst({
        where: {
          resetToken: token,
          resetTokenExpiry: { gt: new Date() }, // Token must still be in the future
        },
      });

      if (!user) {
        return NextResponse.json(
          { error: "Invalid or expired reset token" },
          { status: 400 },
        );
      }

      // Hash the new password
      const passwordHash = await hash(password, 12);

      // Update user and clear the reset token
      await prisma.user.update({
        where: { id: user.id },
        data: {
          passwordHash,
          resetToken: null,
          resetTokenExpiry: null,
        },
      });

      return NextResponse.json(
        { message: "Password has been successfully reset" },
        { status: 200 },
      );
    }

    return NextResponse.json({ error: "Invalid action" }, { status: 400 });
  } catch (error: any) {
    console.error("Password reset error:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { verifyAccessToken } from "@/lib/auth";

export async function POST(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const authHeader = req.headers.get("authorization")!;
    const token = authHeader.split(" ")[1];
    const payload = await verifyAccessToken(token);

    if (!payload) {
      return NextResponse.json(
        {
          success: false,
          error: { code: "UNAUTHORIZED", message: "Unauthorized" },
        },
        { status: 401 },
      );
    }

    const { id } = await params;
    const booking = await prisma.booking.findUnique({
      where: { id },
      include: { hotel: true },
    });

    if (!booking) {
      return NextResponse.json(
        {
          success: false,
          error: { code: "NOT_FOUND", message: "Booking not found" },
        },
        { status: 404 },
      );
    }

    // Only Booker who made it, or Hotel Manager of the hotel, or Admin can cancel
    if (
      booking.userId !== payload.userId &&
      booking.hotel.managerId !== payload.userId &&
      payload.role !== "ADMIN"
    ) {
      return NextResponse.json(
        {
          success: false,
          error: {
            code: "FORBIDDEN",
            message: "Not authorized to cancel this booking",
          },
        },
        { status: 403 },
      );
    }

    if (booking.status !== "PENDING") {
      return NextResponse.json(
        {
          success: false,
          error: {
            code: "VALIDATION_ERROR",
            message: "Only PENDING bookings can be cancelled directly",
          },
        },
        { status: 400 },
      );
    }

    const body = await req.json().catch(() => ({}));

    await prisma.booking.update({
      where: { id },
      data: {
        status: "CANCELLED",
        cancelledAt: new Date(),
        cancelReason: body.reason || "Cancelled by user",
      },
    });

    return NextResponse.json({ success: true, message: "Booking cancelled" });
  } catch (error: unknown) {
    return NextResponse.json(
      {
        success: false,
        error: { code: "INTERNAL_ERROR", message: "Something went wrong" },
      },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { verifyAccessToken } from "@/lib/auth";
import { verifyQRSignature } from "@/lib/qr";

export async function POST(
  req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  try {
    const authHeader = req.headers.get("authorization")!;
    const token = authHeader.split(" ")[1];
    const payload = await verifyAccessToken(token);

    if (!payload) {
      return NextResponse.json(
        {
          success: false,
          error: { code: "UNAUTHORIZED", message: "Invalid token" },
        },
        { status: 401 },
      );
    }

    if (payload.role !== "HOTEL_MANAGER" && payload.role !== "ADMIN") {
      return NextResponse.json(
        {
          success: false,
          error: { code: "FORBIDDEN", message: "Not authorized" },
        },
        { status: 403 },
      );
    }

    const { id: bookingId } = await params;
    const body = await req.json();
    const { qrData, qrSignature } = body;

    if (!qrData || !qrSignature) {
      return NextResponse.json(
        {
          success: false,
          error: {
            code: "VALIDATION_ERROR",
            message: "QR data and signature required",
          },
        },
        { status: 400 },
      );
    }

    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
      include: { hotel: true },
    });

    if (!booking) {
      return NextResponse.json(
        {
          success: false,
          error: { code: "NOT_FOUND", message: "Booking not found" },
        },
        { status: 404 },
      );
    }

    // Verify manager owns this hotel (skip for admin)
    if (
      payload.role === "HOTEL_MANAGER" &&
      booking.hotel.managerId !== payload.userId
    ) {
      return NextResponse.json(
        {
          success: false,
          error: {
            code: "FORBIDDEN",
            message: "Not authorized for this hotel",
          },
        },
        { status: 403 },
      );
    }

    // Verify booking state
    if (booking.status !== "PAID") {
      return NextResponse.json(
        {
          success: false,
          error: {
            code: "INVALID_STATE",
            message: "Booking is not in PAID state",
          },
        },
        { status: 400 },
      );
    }

    // Verify QR Signature
    const isValidSignature = verifyQRSignature(qrData, qrSignature);
    if (!isValidSignature) {
      return NextResponse.json(
        {
          success: false,
          error: {
            code: "INVALID_SIGNATURE",
            message: "QR signature is invalid or forged",
          },
        },
        { status: 400 },
      );
    }

    // Parse the QR data to verify booking ID matches just in case
    const qrPayload = JSON.parse(qrData);
    if (qrPayload.bookingId !== bookingId) {
      return NextResponse.json(
        {
          success: false,
          error: {
            code: "MISMATCH",
            message: "QR code does not match this booking",
          },
        },
        { status: 400 },
      );
    }

    // Check dates (simplified for MVP: check-in is today or past, but not after check-out)
    const now = new Date();
    if (now > booking.checkOutDate) {
      return NextResponse.json(
        {
          success: false,
          error: { code: "EXPIRED", message: "Check-out date has passed" },
        },
        { status: 400 },
      );
    }

    // Process confirmation in transaction
    await prisma.$transaction(async (tx: any) => {
      const db = tx as typeof prisma;

      await db.booking.update({
        where: { id: bookingId },
        data: {
          status: "CONFIRMED",
          confirmedAt: new Date(),
        },
      });

      // Create payout record for the hotel
      await db.payout.create({
        data: {
          hotelId: booking.hotelId,
          bookingId: booking.id,
          amount: booking.hotelPayout,
          status: "PENDING",
        },
      });
    });

    return NextResponse.json({
      success: true,
      message: "Booking confirmed successfully",
    });
  } catch (error: unknown) {
    console.error("Booking Confirm Error:", error);
    return NextResponse.json(
      {
        success: false,
        error: { code: "INTERNAL_ERROR", message: "Something went wrong" },
      },
      { status: 500 },
    );
  }
}

