                  {hotel.whatsappNumber && (
                    <a
                      href={`https://wa.me/${hotel.whatsappNumber.replace(/\D/g, "")}?text=Hi, I made a bank transfer for booking ref: STN-${bookingResult?.bookingId?.slice(0, 8).toUpperCase()}. Please confirm.`}
