import { cookies } from "next/headers";

const getBaseUrl = () => {
  if (typeof window !== "undefined") return ""; // browser should use relative url

  if (process.env.NEXT_PUBLIC_APP_URL) {
    return process.env.NEXT_PUBLIC_APP_URL;
  }
  if (process.env.VERCEL_PROJECT_PRODUCTION_URL) {
    return `https://${process.env.VERCEL_PROJECT_PRODUCTION_URL}`;
  }
  if (process.env.VERCEL_URL) {
    return `https://${process.env.VERCEL_URL}`;
  }

  // Fallback for local development if NEXT_PUBLIC_APP_URL is not set
  return process.env.NODE_ENV === "development"
    ? "http://localhost:3000"
    : "http://localhost:3000";
};

const getHeaders = async (initHeaders?: HeadersInit) => {
  const cookieStore = await cookies();
  const token = cookieStore.get("accessToken")?.value;

  const headers = new Headers(initHeaders);
  headers.set("Content-Type", "application/json");

  if (token && !headers.has("Authorization")) {
    headers.set("Authorization", `Bearer ${token}`);
  }

  return headers;
};

export const apiClient = {
  async get(path: string, options?: RequestInit) {
    const headers = await getHeaders(options?.headers);
    const res = await fetch(`${getBaseUrl()}${path}`, {
      ...options,
      method: "GET",
      headers,
    });
    return res.json();
  },

  async post(path: string, body?: any, options?: RequestInit) {
    const headers = await getHeaders(options?.headers);
    const res = await fetch(`${getBaseUrl()}${path}`, {
      ...options,
      method: "POST",
      headers,
      body: body ? JSON.stringify(body) : undefined,
    });
    return res.json();
  },

  async put(path: string, body?: any, options?: RequestInit) {
    const headers = await getHeaders(options?.headers);
    const res = await fetch(`${getBaseUrl()}${path}`, {
      ...options,
      method: "PUT",
      headers,
      body: body ? JSON.stringify(body) : undefined,
    });
    return res.json();
  },

  async delete(path: string, options?: RequestInit) {
    const headers = await getHeaders(options?.headers);
    const res = await fetch(`${getBaseUrl()}${path}`, {
      ...options,
      method: "DELETE",
      headers,
    });
    return res.json();
  },
};

import { SignJWT, jwtVerify, JWTPayload } from "jose";
import bcrypt from "bcryptjs";

const getAccessSecret = () =>
  new TextEncoder().encode(process.env.JWT_ACCESS_SECRET);
const getRefreshSecret = () =>
  new TextEncoder().encode(process.env.JWT_REFRESH_SECRET);

export interface SessionPayload {
  userId: string;
  email?: string;
  role?: string;
}

export async function signAccessToken(payload: SessionPayload) {
  return new SignJWT(payload as unknown as JWTPayload)
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("15m")
    .sign(getAccessSecret());
}

export async function signRefreshToken(payload: { userId: string }) {
  return new SignJWT(payload as unknown as JWTPayload)
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("7d")
    .sign(getRefreshSecret());
}

export async function verifyAccessToken(token: string) {
  try {
    const { payload } = await jwtVerify(token, getAccessSecret());
    return payload as unknown as SessionPayload;
  } catch (error: unknown) {
    return null;
  }
}

export async function verifyRefreshToken(token: string) {
  try {
    const { payload } = await jwtVerify(token, getRefreshSecret());
    return payload as unknown as { userId: string };
  } catch (error: unknown) {
    return null;
  }
}

export async function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, 12);
}

export async function comparePassword(
  password: string,
  hash: string,
): Promise<boolean> {
  return bcrypt.compare(password, hash);
}

import { cookies } from "next/headers";

export async function getSession() {
  try {
    const cookieStore = await cookies();
    const token = cookieStore.get("accessToken")?.value;
    if (!token) return null;
    return verifyAccessToken(token);
  } catch (error) {
    return null;
  }
}

import { ImageLoaderProps } from "next/image";

export default function customImageLoader({
  src,
  width,
  quality,
}: ImageLoaderProps) {
  // If it's a relative URL (local asset), just return it as is.
  if (src.startsWith("/")) {
    return src;
  }

  // For remote URLs like Unsplash, just return the URL directly
  // In a production app with a CDN (like Cloudinary or AWS Image Optimizer),
  // you would append the width and quality parameters here.
  return src;
}
